html:
{% set company = frappe.get_doc("Company", doc.company) %}
{% set vendor = frappe.get_doc("Supplier", doc.vendor) %}
{% set vendor_address_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Supplier", "link_name": doc.vendor,
"parenttype": "Address"}, "parent") %}
{% set addr = frappe.get_doc("Address", vendor_address_name) if vendor_address_name else None %}

{# ── AUTO-SELECT LETTERHEAD ── #}
{% if doc.letter_head and frappe.db.exists("Letter Head", doc.letter_head) %}
{% set lh_doc = frappe.get_doc("Letter Head", doc.letter_head) %}
{% elif company.default_letter_head and frappe.db.exists("Letter Head", company.default_letter_head) %}
{% set lh_doc = frappe.get_doc("Letter Head", company.default_letter_head) %}
{% else %}
{% set _lh_name = frappe.db.get_value("Letter Head", {"disabled": 0, "is_default": 1}, "name") %}
{% if _lh_name %}
{% set lh_doc = frappe.get_doc("Letter Head", _lh_name) %}
{% else %}
{% set lh_doc = None %}
{% endif %}
{% endif %}
{% set letterhead_img = lh_doc.image if (lh_doc and lh_doc.image) else "" %}

<style>
  @page {
    size: A4 portrait;
    width: 210mm;
    height: 297mm;
    margin-top: 48mm !important;
    margin-bottom: 20mm !important;
    margin-left: 14mm !important;
    margin-right: 14mm !important;
  }

  * {
    box-sizing: border-box;
  }

  /* ── 100% TRANSPARENT - ZERO WHITE BG ANYWHERE ── */
  html,
  body,
  .print-format-gutter,
  .page-break,
  .po-print-wrapper {
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    font-family: Arial, Helvetica, sans-serif !important;
    font-size: 9.5px !important;
    color: #000 !important;
    line-height: 1.3 !important;
  }

  .print-format {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    padding: 0 !important;
    margin-top: 48mm !important;
    margin-bottom: 20mm !important;
    margin-left: 14mm !important;
    margin-right: 14mm !important;
    font-family: Arial, Helvetica, sans-serif !important;
    font-size: 9.5px !important;
    color: #000 !important;
    line-height: 1.3 !important;
  }

  @media screen {
    .print-format-gutter {
      background-color: transparent !important;
      padding: 0 !important;
    }
    .print-format {
      background-color: transparent !important;
      background: transparent !important;
      box-shadow: none !important;
      border-radius: 0 !important;
      padding: 0 !important;
      margin-top: 48mm !important;
      margin-bottom: 20mm !important;
      margin-left: 14mm !important;
      margin-right: 14mm !important;
      max-width: 100% !important;
      min-height: auto !important;
    }
  }

  p {
    margin: 3px 0;
  }

  /* Hide default Frappe headers to avoid duplicate rendering */
  .letter-head,
  .print-heading,
  .letter-head-footer {
    display: none !important;
  }

  .po-print-wrapper {
    width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Fixed-layout formal tables matching exact original specification */
  table.fixed {
    width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
    margin-bottom: 6px;
    word-wrap: break-word;
    background: transparent !important;
    background-color: transparent !important;
  }

  table.fixed th,
  table.fixed td {
    border: 1px solid #000 !important;
    padding: 3px 5px !important;
    vertical-align: top !important;
    font-family: Arial, Helvetica, sans-serif !important;
    font-size: 9px !important;
    color: #000 !important;
    background: transparent !important;
    background-color: transparent !important;
  }

  table.fixed thead th {
    background: transparent !important;
    background-color: transparent !important;
    font-weight: bold !important;
    text-align: left;
  }

  table.fixed .right {
    text-align: right;
  }

  table.fixed .center {
    text-align: center;
  }

  .lbl {
    font-weight: bold !important;
  }

  .section-head {
    background: transparent !important;
    background-color: transparent !important;
    font-weight: bold !important;
    padding: 3px 6px !important;
    border: 1px solid #000 !important;
    border-bottom: none !important;
    font-size: 9px !important;
    text-transform: uppercase !important;
    letter-spacing: 0.5px !important;
  }

  tr {
    page-break-inside: avoid !important;
  }

  .standard-terms-print ol,
  .standard-terms-print ul {
    margin-top: 2px !important;
    margin-bottom: 4px !important;
    padding-left: 18px !important;
  }

  .standard-terms-print li {
    margin-bottom: 2px !important;
  }
</style>

<div class="po-print-wrapper">

  <!-- ── PO TITLE ── -->
  <p
    style="text-align:center; font-size:13px; font-weight:bold; text-decoration:underline; margin:0 0 6px 0; letter-spacing:1px;">
    PURCHASE ORDER</p>

  <!-- ── VENDOR (LEFT) + PO META (RIGHT) ── -->
  <table class="fixed" style="margin-bottom:6px;">
    <colgroup>
      <col style="width:58%">
      <col style="width:22%">
      <col style="width:20%">
    </colgroup>
    <tbody>
      <tr>
        <td rowspan="6" style="vertical-align:top; border-right:2px solid #000 !important;">
          <span class="lbl">{{ vendor.supplier_name }}</span><br>
          {% if addr %}
          {% if addr.address_line1 %}{{ addr.address_line1 }},<br>{% endif %}
          {% if addr.address_line2 %}{{ addr.address_line2 }},<br>{% endif %}
          {% if addr.city %}{{ addr.city }}{% if addr.pincode %} – {{ addr.pincode }}{% endif %}.<br>{% endif %}
          {% if addr.state %}{{ addr.state }},<br>{% endif %}
          {% if addr.country %}{{ addr.country }}.<br>{% endif %}
          {% else %}
          (No address on file)<br>
          {% endif %}
          {% if doc.vendor_gstin %}<br><span class="lbl">GSTIN:</span> {{ doc.vendor_gstin }}{% endif %}
          {% if doc.vendor_pan %}<br><span class="lbl">PAN:</span> {{ doc.vendor_pan }}{% endif %}
        </td>
        <td class="lbl" style="border-bottom:none !important;">Ref No. :-</td>
        <td style="border-bottom:none !important; border-left:1px solid #000 !important;">{{ doc.ref_number or doc.name
          }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important; border-bottom:none !important;">Date :-</td>
        <td
          style="border-top:1px solid #000 !important; border-bottom:none !important; border-left:1px solid #000 !important;">
          {{ doc.get_formatted("po_date") }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important; border-bottom:none !important;">Quotation No. :-
        </td>
        <td
          style="border-top:1px solid #000 !important; border-bottom:none !important; border-left:1px solid #000 !important;">
          {{ doc.quotation_ref or "—" }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important; border-bottom:none !important;">Quotation Date :-
        </td>
        <td
          style="border-top:1px solid #000 !important; border-bottom:none !important; border-left:1px solid #000 !important;">
          {{ doc.get_formatted("quotation_date") or "—" }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important; border-bottom:none !important;">PI No. :-</td>
        <td
          style="border-top:1px solid #000 !important; border-bottom:none !important; border-left:1px solid #000 !important;">
          {{ doc.pi_number or "—" }}</td>
      </tr>
      <tr>
        <td class="lbl" style="border-top:1px solid #000 !important;">Currency :-</td>
        <td style="border-top:1px solid #000 !important; border-left:1px solid #000 !important;">{{ doc.currency }}
          (Rate: {{ doc.exchange_rate or 1 }})</td>
      </tr>
    </tbody>
  </table>

  <!-- ── SALUTATION ── -->
  <p>Dear Sir/Ma'am,</p>
  <p>We are pleased to release this Purchase Order for the supply of <strong>{{ doc.equipment_name or doc.item_code or
      "the specified goods" }}</strong>. Details and specifications are as per below. Please send your acceptance
    confirmation via return email for further processing.</p>

  <!-- ── PRE-CONDITIONS ── -->
  <table class="fixed" style="margin-bottom:6px;">
    <tbody>
      <tr>
        <td>
          The bill should be raised in the name of <strong>{{ company.company_name }}</strong>.
          {% if doc.company_address %}
          <br><span style="color:#333; font-size:8.5px;">{{ doc.company_address | replace("\n", "<br>") }}</span>
          {% else %}
          {% if doc.company_gstin %}<br><strong>GSTIN:</strong> {{ doc.company_gstin }}{% endif %}
          {% if doc.company_pan %}<br><strong>PAN:</strong> {{ doc.company_pan }}{% endif %}
          {% if company.registration_details %}<br><span style="font-size:8.5px;">{{ company.registration_details
            }}</span>{% endif %}
          {% endif %}
        </td>
      </tr>
      <tr>
        <td style="border-top:none !important;">The bill and delivery challan must clearly mention the Purchase Order
          number.</td>
      </tr>
      <tr>
        <td style="border-top:none !important;">The bill must clearly mention the applicable HSN/SAC codes as required
          under GST law.</td>
      </tr>
      <tr>
        <td style="border-top:none !important;">Original signed invoice and relevant documents must be provided at the
          time of material delivery.</td>
      </tr>
      <tr>
        <td style="border-top:none !important;">If nothing contrary is heard within 24 hours from receipt of this PO, it
          will be understood that the Purchase Order is accepted by you.</td>
      </tr>
      <tr>
        <td style="border-top:none !important;">This Purchase Order shall be subject to the jurisdiction of the
          Company's registered office.</td>
      </tr>
    </tbody>
  </table>

  <!-- ── ITEM TABLE ── -->
  <table class="fixed" style="margin-bottom:6px;">
    <colgroup>
      <col style="width:5%">
      <col style="width:30%">
      <col style="width:9%">
      <col style="width:9%">
      <col style="width:6%">
      <col style="width:6%">
      <col style="width:17%">
      <col style="width:18%">
    </colgroup>
    <thead>
      <tr>
        <th class="center">S.No</th>
        <th>Particulars / Item Description</th>
        <th class="center">HSN Code</th>
        <th class="center">Brand / Make</th>
        <th class="center">UOM</th>
        <th class="center">Qty</th>
        <th class="right">Rate ({{ doc.currency }})</th>
        <th class="right">Amount ({{ doc.currency }})</th>
      </tr>
    </thead>
    <tbody>
      {% if doc.items and doc.items|length > 0 %}
      {% for item in doc.items %}
      <tr>
        <td class="center" style="border-top:none !important;">{{ loop.index }}</td>
        <td style="border-top:none !important;">
          <strong>{{ item.equipment_name or item.equipment or "—" }}</strong><br>
          {% if item.brand %}Brand: {{ item.brand }} | {% endif %}
          {% if item.manufacturer %}Mfr: {{ item.manufacturer }}<br>{% endif %}
          {% if item.specification %}<span style="font-size:8.5px;">{{ item.specification }}</span>{% endif %}
        </td>
        <td class="center" style="border-top:none !important;">{{ item.hsn_code or "—" }}</td>
        <td class="center" style="border-top:none !important;">{{ item.brand or "—" }}</td>
        <td class="center" style="border-top:none !important;">{{ item.unit or "Nos" }}</td>
        <td class="center" style="border-top:none !important;">{{ item.quantity }}</td>
        <td class="right" style="border-top:none !important;">{{ doc.currency }} {{ frappe.utils.fmt_money(item.rate,
          currency=doc.currency) }}</td>
        <td class="right" style="border-top:none !important;">{{ doc.currency }} {{
          frappe.utils.fmt_money(item.taxable_amount, currency=doc.currency) }}</td>
      </tr>
      {% endfor %}
      {% else %}
      <tr>
        <td class="center" style="border-top:none !important;">1</td>
        <td style="border-top:none !important;">
          <strong>{{ doc.equipment_name or doc.equipment or "—" }}</strong><br>
          {% if doc.manufacturer %}Mfr: {{ doc.manufacturer }}<br>{% endif %}
          {% if doc.country_of_origin %}Origin: {{ doc.country_of_origin }}<br>{% endif %}
          {% if doc.specification %}<span style="font-size:8.5px;">{{ doc.specification }}</span>{% endif %}
        </td>
        <td class="center" style="border-top:none !important;">{{ doc.hsn_code or "—" }}</td>
        <td class="center" style="border-top:none !important;">{{ doc.brand or "—" }}</td>
        <td class="center" style="border-top:none !important;">{{ doc.unit or "Nos" }}</td>
        <td class="center" style="border-top:none !important;">{{ doc.quantity }}</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("rate") }}</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("taxable_value") }}</td>
      </tr>
      {% endif %}

      <!-- Tax rows (Only if GST is applicable) -->
      {% if doc.gst_type and doc.gst_type != "None" and doc.tax_amount and doc.tax_amount > 0 %}
      {% if doc.gst_type == "CGST + SGST" %}
      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important;">CGST @ {{ (doc.gst_percentage / 2) | round(2) }}%</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("cgst_amount") }}</td>
      </tr>
      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important;">SGST @ {{ (doc.gst_percentage / 2) | round(2) }}%</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("sgst_amount") }}</td>
      </tr>
      {% else %}
      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important;">IGST @ {{ doc.gst_percentage }}%</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("igst_amount") }}</td>
      </tr>
      {% endif %}
      {% endif %}

      {% if doc.freight and doc.freight > 0 %}
      <tr>
        <td colspan="7" class="right" style="border-top:none !important;">Freight Charges</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("freight") }}</td>
      </tr>
      {% endif %}
      {% if doc.insurance and doc.insurance > 0 %}
      <tr>
        <td colspan="7" class="right" style="border-top:none !important;">Insurance Charges</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("insurance") }}</td>
      </tr>
      {% endif %}
      {% if doc.custom_charges and doc.custom_charges > 0 %}
      <tr>
        <td colspan="7" class="right" style="border-top:none !important;">Custom Clearance Charges</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("custom_charges") }}</td>
      </tr>
      {% endif %}
      {% if doc.other_charges and doc.other_charges > 0 %}
      <tr>
        <td colspan="7" class="right" style="border-top:none !important;">Other Charges</td>
        <td class="right" style="border-top:none !important;">{{ doc.get_formatted("other_charges") }}</td>
      </tr>
      {% endif %}

      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important;">TOTAL</td>
        <td class="right lbl" style="border-top:none !important;">{{ doc.currency }} {{
          frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td>
      </tr>
      <tr>
        <td colspan="7" class="right lbl" style="border-top:none !important; font-size:10px;">Total Payable Amount</td>
        <td class="right lbl" style="border-top:none !important; font-size:10px;">{{ doc.currency }} {{
          frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td>
      </tr>
    </tbody>
  </table>

  <!-- ── PAYMENT + LOGISTICS (SIDE BY SIDE) ── -->
  <table width="100%" cellspacing="0" cellpadding="0"
    style="border-collapse:collapse; margin-bottom:6px; table-layout:fixed; background:transparent !important;">
    <colgroup>
      <col style="width:50%">
      <col style="width:4px">
      <col style="width:50%">
    </colgroup>
    <tr>
      <!-- Payment -->
      <td style="vertical-align:top; padding-right:4px; border:none !important; background:transparent !important;">
        <div class="section-head">PAYMENT DETAILS</div>
        <table class="fixed" style="margin-bottom:0;">
          <colgroup>
            <col style="width:45%">
            <col style="width:55%">
          </colgroup>
          <tbody>
            <tr>
              <td class="lbl">Payment Terms</td>
              <td>{{ doc.payment_terms or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Advance %</td>
              <td style="border-top:none !important;">{{ doc.advance_percentage or 0 }}%</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Advance Amount</td>
              <td style="border-top:none !important;">{{ doc.get_formatted("advance_amount") }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Balance Due</td>
              <td class="lbl" style="border-top:none !important;">{{ doc.get_formatted("balance_due") }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Vendor Bank</td>
              <td style="border-top:none !important;">{{ doc.vendor_bank_name or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">A/C No.</td>
              <td style="border-top:none !important;">{{ doc.vendor_account_number or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">IFSC Code</td>
              <td style="border-top:none !important;">{{ doc.vendor_ifsc or "—" }}</td>
            </tr>
          </tbody>
        </table>
      </td>
      <td style="border:none !important; background:transparent !important;"></td>
      <!-- Logistics -->
      <td style="vertical-align:top; padding-left:4px; border:none !important; background:transparent !important;">
        <div class="section-head">LOGISTICS &amp; SHIPPING</div>
        <table class="fixed" style="margin-bottom:0;">
          <colgroup>
            <col style="width:45%">
            <col style="width:55%">
          </colgroup>
          <tbody>
            <tr>
              <td class="lbl">Port of Shipment</td>
              <td>{{ doc.port or company.custom_default_port or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Shipment Type</td>
              <td style="border-top:none !important;">{{ doc.shipment_type or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Expected Delivery</td>
              <td style="border-top:none !important;">{{ doc.get_formatted("expected_delivery") or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">Delivery Location</td>
              <td style="border-top:none !important;">{{ doc.delivery_location or "—" }}</td>
            </tr>
            {% if doc.warehouse %}
            <tr>
              <td class="lbl" style="border-top:none !important;">Destination Warehouse</td>
              <td style="border-top:none !important;">{{ doc.warehouse|replace('\n', '<br>') }}</td>
            </tr>
            {% endif %}
            <tr>
              <td class="lbl" style="border-top:none !important;">Container No.</td>
              <td style="border-top:none !important;">{{ doc.container_number or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">SRI GSTIN</td>
              <td style="border-top:none !important;">{{ company.tax_id or "—" }}</td>
            </tr>
            <tr>
              <td class="lbl" style="border-top:none !important;">IEC Code</td>
              <td style="border-top:none !important;">{{ company.custom_import_export_code or "AFTFS2557J" }}</td>
            </tr>
          </tbody>
        </table>
      </td>
    </tr>
  </table>

  <!-- ── PAGE BREAK: CLEAN SPLIT TO PAGE 2 ── -->
  <div style="page-break-before: always;"></div>

  <!-- ── TERMS & CONDITIONS (PAGE 2) ── -->
  {% if doc.standard_terms or doc.custom_terms %}
  <p style="margin:0 0 4px 0;"><strong><u>Terms &amp; Conditions :-</u></strong></p>
  <table class="fixed" style="margin-bottom:8px;">
    <tbody>
      <tr>
        <td style="line-height:1.4;">
          {% if doc.standard_terms %}
          {% for row in doc.standard_terms %}
          {% if row.standard_term and frappe.db.exists("Terms and Conditions", row.standard_term) %}
          {% set st_doc = frappe.get_doc("Terms and Conditions", row.standard_term) %}
          <div class="standard-terms-print" style="margin-bottom: 6px;">
            <strong>{{ row.standard_term }}</strong>
            <div>{{ st_doc.terms }}</div>
          </div>
          {% endif %}
          {% endfor %}
          {% endif %}
          {% if doc.custom_terms %}
          <div class="custom-terms-print" style="margin-top: 6px;">
            {{ doc.custom_terms }}
          </div>
          {% endif %}
        </td>
      </tr>
    </tbody>
  </table>
  {% else %}
  <p style="margin:0 0 4px 0;"><strong><u>Terms &amp; Conditions :-</u></strong></p>
  <table class="fixed" style="margin-bottom:8px;">
    <tbody>
      <tr>
        <td style="line-height:1.4;">
          1) The prices are Nett &amp; Ex-Godown / Ex-Works unless otherwise specified.<br>
          2) Discount: As mentioned in this Purchase Order.<br>
          3) Packing Charges: As per actuals. Supplier must pack goods in a manner compliant with export norms and
          handling safety.<br>
          4) Inspection: Pre-dispatch inspection at supplier premises or at port if requested.<br>
          5) Warranty: Standard manufacturer warranty applies from date of delivery and commissioning.<br>
          6) Delivery Schedule: Goods must be dispatched on or before the committed delivery date.<br>
          7) Jurisdiction: Subject to local registered office jurisdiction.
        </td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  <!-- ── ATTACHED DOCUMENTS INDEX (IF ANY) ── -->
  {% set attached_docs = [] %}
  {% if doc.quotation_pdf %}
  {% set _ = attached_docs.append({"category": "Vendor Quotation", "filename": doc.quotation_pdf.split('/')[-1]}) %}
  {% endif %}
  {% if doc.supplier_quotation_attachment %}
  {% set _ = attached_docs.append({"category": "Supplier Quotation Document", "filename":
  doc.supplier_quotation_attachment.split('/')[-1]}) %}
  {% endif %}
  {% if doc.quotation_comparision %}
  {% set _ = attached_docs.append({"category": "Quotation Comparison Sheet", "filename":
  doc.quotation_comparision.split('/')[-1]}) %}
  {% endif %}
  {% if doc.inspection_report %}
  {% set _ = attached_docs.append({"category": "Pre-dispatch Inspection Report", "filename":
  doc.inspection_report.split('/')[-1]}) %}
  {% endif %}

  {% if attached_docs | length > 0 %}
  <div class="section-head">ATTACHED DOCUMENTS SUMMARY</div>
  <table class="fixed" style="margin-bottom:8px;">
    <colgroup>
      <col style="width:8%">
      <col style="width:42%">
      <col style="width:50%">
    </colgroup>
    <thead>
      <tr>
        <th class="center">S.No</th>
        <th>Document Category / Label</th>
        <th>File Name / Reference</th>
      </tr>
    </thead>
    <tbody>
      {% for item in attached_docs %}
      <tr>
        <td class="center" style="border-top:none !important;">{{ loop.index }}</td>
        <td style="border-top:none !important;"><strong>{{ item.category }}</strong></td>
        <td style="border-top:none !important;">{{ item.filename }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  {% endif %}

  {% if doc.remarks %}
  <div class="section-head">NOTE</div>
  <table class="fixed" style="margin-bottom:8px;">
    <tbody>
      <tr>
        <td>{{ doc.remarks }}</td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  <!-- ── SIGNATURES ── -->
  <table width="100%" cellspacing="0" cellpadding="0"
    style="border-collapse:collapse; margin-top:18px; margin-bottom:8px; table-layout:fixed; background:transparent !important;">
    <colgroup>
      <col style="width:33%">
      <col style="width:34%">
      <col style="width:33%">
    </colgroup>
    <tr style="background:transparent !important;">
      <td
        style="text-align:center; border-top:1px solid #000 !important; padding-top:4px; border-left:none !important; border-right:none !important; border-bottom:none !important; background:transparent !important;">
        <strong>Prepared By</strong><br>
        <span style="font-size:9px; color:#333;">{{ doc.prepared_by or "Administrator" }}</span>
      </td>
      <td
        style="text-align:center; border-top:1px solid #000 !important; padding-top:4px; border-left:none !important; border-right:none !important; border-bottom:none !important; background:transparent !important;">
        <strong>Verified By</strong><br>
        <span style="font-size:9px; color:#333;">{{ doc.verified_by or "Administrator" }}</span>
      </td>
      <td
        style="text-align:center; border-top:1px solid #000 !important; padding-top:4px; border-left:none !important; border-right:none !important; border-bottom:none !important; background:transparent !important;">
        <strong>Authorized Signatory</strong><br>
        <span style="font-size:9px; color:#333;">For {{ company.company_name }}</span>
      </td>
    </tr>
  </table>

</div>
